BEGIN;

INSERT INTO public.layers (id, name, sort_order, description) VALUES
  ('application', 'Application', 1, 'Code paths, ORMs and request handlers.'),
  ('api', 'API & Resilience', 2, 'How services call each other and survive failure.'),
  ('data', 'Data', 3, 'Databases, queries, transactions and replication.'),
  ('caching', 'Caching', 4, 'Caches and the failure modes they introduce.'),
  ('runtime', 'Runtime', 5, 'Memory management, threads and event loops.'),
  ('network', 'Network', 6, 'TCP, TLS, DNS and connection behaviour.'),
  ('os', 'Operating System', 7, 'Scheduler, kernel limits and resource isolation.'),
  ('distributed', 'Distributed Systems', 8, 'System-wide dynamics across many services.')
ON CONFLICT (id) DO UPDATE SET
    name = excluded.name,
    sort_order = excluded.sort_order,
    description = excluded.description,
    updated_at = now();

INSERT INTO public.concepts (id, slug, name, layer_id, description, problem, why, mechanism, tradeoffs, better_alternative) VALUES
  ('n-plus-one', 'n-plus-one', 'N+1 Queries', 'application', 'One query per row instead of one query per set.', 'Latency grows linearly with result size.', NULL, 'Lazy-loaded relations inside a loop issue a database round-trip per item.', 'Eager loading can over-fetch rows and columns you never use.', 'Batch with joins, IN-lists or a dataloader keyed by id.'),
  ('unbounded-query', 'unbounded-query', 'Unbounded Query', 'application', 'A query with no LIMIT whose result grows with the data.', 'Fine in development, catastrophic once a table reaches millions of rows.', NULL, 'The whole result is materialised in database memory, on the wire and in the app heap.', 'Limits force callers to handle partial results.', 'Always paginate; enforce a hard maximum page size.'),
  ('missing-pagination', 'missing-pagination', 'Missing Pagination', 'application', 'An endpoint returns every record in one response.', 'Response size and latency grow without bound.', NULL, 'Each request serialises the full collection and holds it in memory.', 'Offset pagination gets slow on deep pages.', 'Keyset (cursor) pagination on an indexed column.'),
  ('hot-path-allocation', 'hot-path-allocation', 'Hot-Path Allocation', 'application', 'Creating many short-lived objects in code that runs per request.', 'Throughput drops and tail latency rises under load.', NULL, 'High allocation rate fills the young generation and forces frequent collections.', 'Object pooling adds complexity and its own bugs.', 'Reuse buffers, avoid boxing, profile allocations before optimising.'),
  ('synchronous-fanout', 'synchronous-fanout', 'Synchronous Fan-out', 'application', 'One request calls many downstream services and waits for all of them.', 'Overall latency is set by the slowest dependency.', NULL, 'With N parallel calls, the chance of hitting at least one slow tail grows with N.', 'Async designs are harder to reason about and debug.', 'Reduce fan-out, set per-call deadlines, return partial results.'),
  ('retry-storm', 'retry-storm', 'Retry Storm', 'api', 'Clients retry in lockstep and multiply load on a struggling service.', 'A brief slowdown turns into a full outage.', NULL, 'Every failure spawns more requests; retries at each layer multiply geometrically.', 'Fewer retries mean more user-visible errors during blips.', 'Exponential backoff with jitter, retry budgets, retry at one layer only.'),
  ('thundering-herd', 'thundering-herd', 'Thundering Herd', 'api', 'Many waiting clients wake up and act at the same instant.', 'A recovering service is knocked over the moment it comes back.', NULL, 'A shared trigger (restart, expiry, timer) synchronises otherwise independent clients.', 'Spreading load out delays some clients.', 'Add jitter, stagger wake-ups, admit clients gradually.'),
  ('missing-timeout', 'missing-timeout', 'Missing Timeout', 'api', 'A network call that can wait forever.', 'One stuck dependency ties up threads and connections indefinitely.', NULL, 'Without a deadline, slow responses hold resources until the caller''s pool is empty.', 'Timeouts that are too short cause spurious failures and retries.', 'Set timeouts from measured p99.9 latency and propagate deadlines.'),
  ('exponential-backoff', 'exponential-backoff', 'Exponential Backoff with Jitter', 'api', 'Wait progressively longer, randomised intervals between retries.', 'Fixed retry intervals keep clients synchronised.', NULL, 'Doubling the delay sheds load; random jitter breaks synchronisation.', 'Slower recovery for individual requests.', 'Combine with a retry budget and circuit breaker.'),
  ('circuit-breaker', 'circuit-breaker', 'Circuit Breaker', 'api', 'Stop calling a dependency that keeps failing.', 'Calls to a dead dependency waste resources and add latency.', NULL, 'After an error threshold the breaker opens and fails fast, then probes to recover.', 'Mis-tuned thresholds can trip on healthy services.', 'Tune on error rate over a window, not absolute counts.'),
  ('rate-limiting', 'rate-limiting', 'Rate Limiting', 'api', 'Cap how many requests a client may send per unit of time.', 'One heavy client can starve everyone else.', NULL, 'Token or leaky buckets admit bursts up to a limit and reject the rest.', 'Legitimate spikes get rejected.', 'Per-tenant limits with clear 429 responses and Retry-After headers.'),
  ('idempotency-key', 'idempotency-key', 'Idempotency Keys', 'api', 'A client-supplied key that makes repeated requests safe.', 'Retries can double-charge or duplicate writes.', NULL, 'The server stores the key with the result and replays it for duplicates.', 'Requires durable storage and a key expiry policy.', 'Design write APIs to be naturally idempotent where possible.'),
  ('bulkhead', 'bulkhead', 'Bulkhead', 'api', 'Isolate resources per dependency so one failure cannot drain them all.', 'A single slow dependency exhausts a shared pool.', NULL, 'Separate thread or connection pools cap the blast radius of each dependency.', 'Partitioned pools are less efficient when idle.', 'Size bulkheads from each dependency''s concurrency needs.'),
  ('connection-pool-exhaustion', 'connection-pool-exhaustion', 'Connection Pool Exhaustion', 'data', 'Every database connection is checked out; new work waits.', 'Requests time out even though the database looks idle.', NULL, 'Slow queries or leaked connections hold slots longer than the arrival rate allows (Little''s law).', 'Bigger pools push contention into the database itself.', 'Size pools by Little''s law; fix slow queries; add a pooler.'),
  ('lock-contention', 'lock-contention', 'Lock Contention', 'data', 'Transactions wait on row or table locks held by others.', 'Throughput collapses under concurrent writes to hot rows.', NULL, 'Waiters queue behind lock holders; long holders create long queues.', 'Optimistic concurrency moves the cost into retries.', 'Shorten transactions, shard hot rows, prefer append-only writes.'),
  ('missing-index', 'missing-index', 'Missing Index', 'data', 'A frequent query filters on a column with no index.', 'Queries slow down as the table grows.', NULL, 'The planner has no choice but to scan every row.', 'Each index slows writes and uses storage.', 'Index columns used in WHERE, JOIN and ORDER BY of hot queries.'),
  ('full-table-scan', 'full-table-scan', 'Full Table Scan', 'data', 'The database reads every row to answer a query.', 'Heavy I/O and CPU that evict useful pages from cache.', NULL, 'Sequential reads of the entire table, often due to a missing or unusable index.', 'For small tables or large result fractions a scan is actually cheaper.', 'Check EXPLAIN; add or fix the index; rewrite non-sargable predicates.'),
  ('long-transaction', 'long-transaction', 'Long-Running Transaction', 'data', 'A transaction left open for seconds or minutes.', 'Holds locks and blocks vacuum, bloating tables.', NULL, 'Locks and old row versions are retained until commit.', 'Splitting work loses atomicity.', 'Keep transactions short; never wait on network calls inside one.'),
  ('deadlock', 'deadlock', 'Deadlock', 'data', 'Two transactions each wait for a lock the other holds.', 'One transaction is killed; under load this repeats constantly.', NULL, 'Locks acquired in inconsistent order form a cycle.', 'Coarser locking prevents deadlocks but reduces concurrency.', 'Acquire locks in a consistent order; retry aborted transactions.'),
  ('replication-lag', 'replication-lag', 'Replication Lag', 'data', 'Replicas fall behind the primary.', 'Users read stale data right after writing.', NULL, 'Replicas apply the write log more slowly than the primary produces it.', 'Reading from the primary loses the scaling benefit.', 'Read-your-writes routing; monitor lag; throttle bulk writes.'),
  ('connection-pooler', 'connection-pooler', 'Connection Pooler', 'data', 'A proxy (e.g. PgBouncer) that multiplexes many clients onto few connections.', 'Each database connection costs memory and a process.', NULL, 'Transaction-level pooling lends a server connection only while a transaction runs.', 'Breaks session-level features like prepared statements in some modes.', 'Use transaction pooling with session state kept in the app.'),
  ('query-plan-regression', 'query-plan-regression', 'Query Plan Regression', 'data', 'The planner suddenly picks a worse plan for an unchanged query.', 'A query that took milliseconds now takes seconds.', NULL, 'Stale statistics or parameter skew mislead the cost model.', 'Pinning plans prevents adapting to data changes.', 'Keep statistics fresh; capture plans; alert on plan changes.'),
  ('write-amplification', 'write-amplification', 'Write Amplification', 'data', 'One logical write causes many physical writes.', 'Disks saturate well below expected throughput.', NULL, 'Indexes, WAL, page splits and compaction each rewrite the data.', 'Fewer indexes make reads slower.', 'Drop unused indexes; batch writes; choose storage engines deliberately.'),
  ('cache-stampede', 'cache-stampede', 'Cache Stampede', 'caching', 'A popular cache entry expires and every request recomputes it at once.', 'The backing store is flooded the instant a key expires.', NULL, 'All concurrent misses go to the origin before any of them repopulates the cache.', 'Locking adds latency for waiters.', 'Request coalescing, early probabilistic refresh, stale-while-revalidate.'),
  ('request-coalescing', 'request-coalescing', 'Request Coalescing', 'caching', 'Merge identical in-flight requests into one.', 'Duplicate work multiplies load during misses.', NULL, 'The first request fetches; concurrent identical requests wait for its result.', 'One slow fetch delays every waiter.', 'Coalesce with a timeout and serve stale data when possible.'),
  ('cold-cache', 'cold-cache', 'Cold Cache', 'caching', 'A cache with nothing in it after a deploy or restart.', 'Origin load spikes and latency jumps until the cache warms.', NULL, 'Every request misses until the working set is reloaded.', 'Pre-warming costs time during deploys.', 'Warm caches before taking traffic; roll restarts gradually.'),
  ('hot-key', 'hot-key', 'Hot Key', 'caching', 'A single key receives a disproportionate share of traffic.', 'One shard or node saturates while others idle.', NULL, 'Consistent hashing sends every request for the key to the same node.', 'Replicating the key complicates invalidation.', 'Local in-process caching or key splitting for hot entries.'),
  ('cache-invalidation', 'cache-invalidation', 'Cache Invalidation', 'caching', 'Removing or updating cached data when the source changes.', 'Users see stale or inconsistent data.', NULL, 'Writes and invalidations race; deletes can arrive before a stale refill.', 'Short TTLs reduce staleness but increase origin load.', 'Versioned keys or write-through with explicit TTL bounds.'),
  ('gc-pause', 'gc-pause', 'GC Pause', 'runtime', 'The runtime stops application threads to reclaim memory.', 'Tail latency spikes unrelated to request work.', NULL, 'Heap pressure triggers stop-the-world collection phases.', 'Larger heaps pause less often but can pause longer.', 'Reduce allocation; use a low-pause collector; right-size the heap.'),
  ('heap-pressure', 'heap-pressure', 'Heap Pressure', 'runtime', 'The live heap sits close to its maximum.', 'Collections run constantly, eating CPU.', NULL, 'Little free space means every allocation burst triggers a GC.', 'Raising the heap limit risks the container''s memory limit.', 'Find what retains memory; reduce caches held in heap.'),
  ('memory-leak', 'memory-leak', 'Memory Leak', 'runtime', 'Memory that is never released.', 'The process slows down and is eventually killed.', NULL, 'Unbounded caches, listeners or global maps keep objects reachable.', 'Periodic restarts hide the leak instead of fixing it.', 'Heap snapshots over time; bound every cache.'),
  ('thread-pool-starvation', 'thread-pool-starvation', 'Thread Pool Starvation', 'runtime', 'Every worker thread is blocked.', 'The service stops accepting work while CPU sits idle.', NULL, 'Blocking I/O on a bounded pool parks all workers at once.', 'Unbounded pools trade starvation for memory blowups.', 'Async I/O or a separate bulkhead pool for blocking work.'),
  ('event-loop-blocking', 'event-loop-blocking', 'Event Loop Blocking', 'runtime', 'CPU-heavy or synchronous work runs on a single-threaded event loop.', 'Every concurrent request stalls together.', NULL, 'Nothing else can run until the blocking task yields.', 'Worker threads add serialisation and coordination cost.', 'Move CPU work to workers; chunk long tasks.'),
  ('async-io', 'async-io', 'Async I/O', 'runtime', 'Non-blocking I/O that frees threads while waiting.', 'Thread-per-request wastes threads waiting on I/O.', NULL, 'The kernel signals readiness (epoll, io_uring); few threads serve many connections.', 'Harder debugging and a risk of blocking the loop.', 'Use async for I/O-bound services; keep CPU work off the loop.'),
  ('tcp-retransmits', 'tcp-retransmits', 'TCP Retransmits', 'network', 'Lost packets are resent after a timeout.', 'Requests stall for hundreds of milliseconds.', NULL, 'Packet loss triggers retransmission timeouts and shrinks the congestion window.', 'Aggressive timeouts cause spurious retransmits.', 'Fix the lossy link; tune minimum RTO; consider QUIC.'),
  ('head-of-line-blocking', 'head-of-line-blocking', 'Head-of-Line Blocking', 'network', 'One slow item at the front of a queue delays everything behind it.', 'Unrelated requests on the same connection stall together.', NULL, 'TCP delivers bytes in order; one lost packet blocks all multiplexed streams.', 'More connections cost handshakes and memory.', 'HTTP/3 (QUIC) independent streams; separate queues for slow work.'),
  ('dns-latency', 'dns-latency', 'DNS Resolution Latency', 'network', 'Time spent resolving hostnames before connecting.', 'Sporadic slow requests with no server-side cause.', NULL, 'Uncached lookups, resolver timeouts and search-domain expansion add round-trips.', 'Long TTLs slow down failover.', 'Local caching resolver; use fully-qualified names.'),
  ('connection-churn', 'connection-churn', 'Connection Churn', 'network', 'Opening and closing connections for each request.', 'CPU and latency wasted on handshakes; ephemeral ports run out.', NULL, 'Every new connection pays TCP and TLS setup and leaves a TIME_WAIT socket.', 'Long-lived connections can pin load to one backend.', 'Keep-alive and connection pooling.'),
  ('keep-alive', 'keep-alive', 'Connection Keep-Alive', 'network', 'Reuse one connection for many requests.', 'Per-request handshakes add latency.', NULL, 'Idle connections stay open and are reused by later requests.', 'Stale connections fail if the server closes them silently.', 'Match client idle timeouts below server timeouts.'),
  ('tls-handshake-cost', 'tls-handshake-cost', 'TLS Handshake Cost', 'network', 'Cryptographic setup before the first byte of data.', 'Extra round-trips and CPU on every new connection.', NULL, 'Key exchange and certificate validation take 1–2 RTTs and asymmetric crypto.', 'Session resumption has replay considerations.', 'TLS 1.3, session resumption and connection reuse.'),
  ('cpu-throttling', 'cpu-throttling', 'CPU Throttling', 'os', 'The kernel caps a container''s CPU time per period.', 'Latency spikes despite low average CPU.', NULL, 'The CFS quota is used up early in each 100 ms period, so threads wait for the next one.', 'Removing limits risks noisy-neighbour effects.', 'Raise the quota, reduce thread count, or use requests without limits.'),
  ('context-switching', 'context-switching', 'Excessive Context Switching', 'os', 'The CPU spends its time switching between threads.', 'High CPU usage with little useful work.', NULL, 'Far more runnable threads than cores force the scheduler to swap constantly.', 'Fewer threads can underuse cores during I/O waits.', 'Size thread pools near core count for CPU-bound work.'),
  ('fd-exhaustion', 'fd-exhaustion', 'File Descriptor Exhaustion', 'os', 'The process hits its open-file limit.', 'New connections and file opens fail with EMFILE.', NULL, 'Leaked sockets or many idle connections consume descriptors.', 'Raising limits only delays a leak.', 'Close resources reliably; raise ulimit to match expected load.'),
  ('page-cache-thrashing', 'page-cache-thrashing', 'Page Cache Thrashing', 'os', 'The working set does not fit in memory, so pages are constantly evicted.', 'Disk I/O explodes and reads become slow.', NULL, 'The kernel evicts pages that are needed again moments later.', 'More memory costs money.', 'Shrink the working set or add memory; avoid scans that pollute cache.'),
  ('noisy-neighbor', 'noisy-neighbor', 'Noisy Neighbour', 'os', 'Another workload on the same host consumes shared resources.', 'Unexplained performance swings.', NULL, 'Shared CPU caches, memory bandwidth, disks and NICs are contended.', 'Dedicated hosts cost more.', 'Resource isolation, dedicated nodes for critical services.'),
  ('cascading-failure', 'cascading-failure', 'Cascading Failure', 'distributed', 'A failure in one component overloads others until the system collapses.', 'A local problem becomes a site-wide outage.', NULL, 'Load from a failed node shifts to survivors, which then fail too.', 'Shedding load deliberately drops some users.', 'Load shedding, circuit breakers, bulkheads and capacity headroom.'),
  ('load-shedding', 'load-shedding', 'Load Shedding', 'distributed', 'Deliberately rejecting work when overloaded.', 'Accepting everything makes every request slow.', NULL, 'Reject early and cheaply once queue length or latency crosses a threshold.', 'Some requests are refused that might have succeeded.', 'Prioritise critical traffic; shed lowest-priority first.'),
  ('backpressure', 'backpressure', 'Backpressure', 'distributed', 'Signalling producers to slow down when consumers fall behind.', 'Unbounded queues hide overload until memory runs out.', NULL, 'Bounded buffers block or reject upstream when full.', 'Producers must handle being slowed or rejected.', 'Bound every queue; propagate pressure to the edge.'),
  ('queue-buildup', 'queue-buildup', 'Queue Buildup', 'distributed', 'Work arrives faster than it is processed and queues grow.', 'Latency climbs steadily, then requests time out.', NULL, 'Once utilisation nears 100%, queueing delay grows sharply.', 'Bigger queues only trade errors for latency.', 'Bound queues; keep utilisation below saturation.'),
  ('tail-latency', 'tail-latency', 'Tail Latency', 'distributed', 'The slowest few percent of requests (p99, p99.9).', 'At scale, most user requests touch at least one slow tail.', NULL, 'GC, queuing, retransmits and contention create rare but large delays that fan-out amplifies.', 'Optimising the tail costs extra capacity.', 'Hedged requests, deadline propagation, fewer dependencies.'),
  ('hedged-requests', 'hedged-requests', 'Hedged Requests', 'distributed', 'Send a duplicate request if the first is slow, and use whichever answers first.', 'A single slow replica dictates latency.', NULL, 'After a p95 delay a second copy goes to another replica; the loser is cancelled.', 'Adds a few percent of extra load.', 'Hedge only idempotent reads; cap the hedge rate.')
ON CONFLICT (id) DO UPDATE SET
    slug = excluded.slug,
    name = excluded.name,
    layer_id = excluded.layer_id,
    description = excluded.description,
    problem = excluded.problem,
    why = excluded.why,
    mechanism = excluded.mechanism,
    tradeoffs = excluded.tradeoffs,
    better_alternative = excluded.better_alternative,
    updated_at = now();

