  ('hedged-requests--mitigates--tail-latency', 'hedged-requests', 'tail-latency', 'MITIGATES'),
  ('hedged-requests--requires--idempotency-key', 'hedged-requests', 'idempotency-key', 'REQUIRES'),
  ('hedged-requests--amplifies--retry-storm', 'hedged-requests', 'retry-storm', 'AMPLIFIES')
ON CONFLICT (id) DO UPDATE SET
    source_id = excluded.source_id,
    target_id = excluded.target_id,
    type = excluded.type,
    updated_at = now();

INSERT INTO public.sources (id, kind, title, author, year, url, note) VALUES
  ('ddia', 'BOOK', 'Designing Data-Intensive Applications', 'Martin Kleppmann', 2017, 'https://dataintensive.net/', 'The single best account of replication, transactions and the failure modes that live between them.'),
  ('sre-book', 'BOOK', 'Site Reliability Engineering', 'Beyer, Jones, Petoff & Murphy (Google)', 2016, 'https://sre.google/sre-book/table-of-contents/', 'Where overload, cascading failure and error budgets were first written down for a general audience.'),
  ('sre-workbook', 'BOOK', 'The Site Reliability Workbook', 'Beyer, Murphy, Rensin, Kawahara & Thorne (Google)', 2018, 'https://sre.google/workbook/table-of-contents/', 'The practical companion: SLOs, percentile targets and the arithmetic behind latency objectives.'),
  ('release-it', 'BOOK', 'Release It! Design and Deploy Production-Ready Software', 'Michael T. Nygard', 2018, 'https://pragprog.com/titles/mnee2/release-it-second-edition/', 'The stability patterns and antipatterns vocabulary — timeout, circuit breaker, bulkhead — in one place.'),
  ('systems-performance', 'BOOK', 'Systems Performance: Enterprise and the Cloud', 'Brendan Gregg', 2020, 'https://www.brendangregg.com/systems-performance-2nd-edition-book.html', 'The methodology and the counters: CPU, memory, file system, disk and network, each with the tool that shows it.'),
  ('hpbn', 'BOOK', 'High Performance Browser Networking', 'Ilya Grigorik', 2013, 'https://hpbn.co/', 'Free online. The clearest explanation of handshakes, keep-alive and head-of-line blocking on the wire.'),
  ('tail-at-scale', 'PAPER', 'The Tail at Scale', 'Jeffrey Dean & Luiz André Barroso', 2013, 'https://cacm.acm.org/research/the-tail-at-scale/', 'Why fan-out turns a rare slow response into a common one, and what hedging actually buys.'),
  ('metastable-failures', 'PAPER', 'Metastable Failures in Distributed Systems', 'Bronson, Aghayev, Charapko & Zhu', 2021, 'https://sigops.org/s/conferences/hotos/2021/papers/hotos21-s11-bronson.pdf', 'Names the state where load is gone but the system stays down: the sustaining effect outlives the trigger.'),
  ('memcache-fb', 'PAPER', 'Scaling Memcache at Facebook', 'Nishtala et al. (NSDI)', 2013, 'https://www.usenix.org/system/files/conference/nsdi13/nsdi13-final170_update.pdf', 'Leases, stale sets and hot keys — the paper that defined how large caches actually behave.'),
  ('lsm-tree', 'PAPER', 'The Log-Structured Merge-Tree (LSM-Tree)', 'Patrick O''Neil, Edward Cheng, Dieter Gawlick & Elizabeth O''Neil', 1996, 'https://www.cs.umb.edu/~poneil/lsmtree.pdf', 'The original write-amplification trade-off: cheap writes now, compaction work later.'),
  ('littles-law', 'ARTICLE', 'Little''s Law as Viewed on its 50th Anniversary', 'John D. C. Little', 2011, 'https://www.informs.org/content/download/255808/2414681/file/little.pdf', 'L = λW. Pool sizing, thread counts and queue depth are all this one equation.'),
  ('fail-at-scale', 'ARTICLE', 'Fail at Scale', 'Ben Maurer (ACM Queue)', 2015, 'https://queue.acm.org/detail.cfm?id=2839461', 'Facebook''s taxonomy of overload: thundering herds, poisoned caches and the controls that stop them.'),
  ('backoff-jitter', 'ARTICLE', 'Exponential Backoff and Jitter', 'Marc Brooker (AWS)', 2015, 'https://aws.amazon.com/blogs/architecture/exponential-backoff-and-jitter/', 'Shows with simulation why backoff without jitter still synchronises clients.'),
  ('timeouts-retries', 'ARTICLE', 'Timeouts, Retries and Backoff with Jitter', 'Marc Brooker (Amazon Builders'' Library)', NULL, 'https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/', 'Retry budgets and token buckets: how to retry without becoming the outage.'),
  ('builders-load-shedding', 'ARTICLE', 'Using Load Shedding to Avoid Overload', 'David Yanacek (Amazon Builders'' Library)', NULL, 'https://aws.amazon.com/builders-library/using-load-shedding-to-avoid-overload/', 'Why a fast rejection is a better answer than a slow success, and where to put the decision.'),
  ('builders-queue-backlogs', 'ARTICLE', 'Avoiding Insurmountable Queue Backlogs', 'David Yanacek (Amazon Builders'' Library)', NULL, 'https://aws.amazon.com/builders-library/avoiding-insurmountable-queue-backlogs/', 'Queues hide overload until the backlog is longer than the useful lifetime of its contents.'),
  ('builders-fairness', 'ARTICLE', 'Fairness in Multi-Tenant Systems', 'David Yanacek (Amazon Builders'' Library)', NULL, 'https://aws.amazon.com/builders-library/fairness-in-multi-tenant-systems/', 'How one tenant''s workload becomes everyone''s latency, and the quota mechanics that prevent it.'),
  ('caching-strategies', 'ARTICLE', 'Caching Challenges and Strategies', 'Matt Brinkley & Jas Chhabra (Amazon Builders'' Library)', NULL, 'https://aws.amazon.com/builders-library/caching-challenges-and-strategies/', 'Modality, cold caches and the bimodal behaviour a cache introduces into a system.'),
  ('fowler-circuit-breaker', 'ARTICLE', 'CircuitBreaker', 'Martin Fowler', 2014, 'https://martinfowler.com/bliki/CircuitBreaker.html', 'The canonical description of the three states and what the half-open probe is for.'),
  ('stripe-rate-limiters', 'ARTICLE', 'Scaling Your API with Rate Limiters', 'Paul Tarjan (Stripe)', 2017, 'https://stripe.com/blog/rate-limiters', 'Four limiter types in production, including load shedders that protect critical traffic first.'),
  ('timewait-bernat', 'ARTICLE', 'Coping with the TCP TIME-WAIT State on Busy Linux Servers', 'Vincent Bernat', 2014, 'https://vincent.bernat.ch/en/blog/2014-tcp-time-wait-state-linux', 'What TIME-WAIT costs, why the usual sysctl advice is wrong, and when connection churn actually bites.'),
  ('use-method', 'ARTICLE', 'The USE Method', 'Brendan Gregg', 2012, 'https://www.brendangregg.com/usemethod.html', 'Utilisation, saturation, errors — a checklist that finds resource bottlenecks without guesswork.'),
  ('use-the-index-luke', 'ARTICLE', 'Use The Index, Luke!', 'Markus Winand', NULL, 'https://use-the-index-luke.com/', 'SQL indexing explained from the developer''s side: what the plan does with your WHERE clause.'),
  ('no-offset', 'ARTICLE', 'Pagination Done the PostgreSQL Way (No Offset)', 'Markus Winand', NULL, 'https://use-the-index-luke.com/no-offset', 'Why OFFSET pagination degrades with depth and what keyset pagination replaces it with.'),
  ('rfc6298', 'RFC', 'RFC 6298: Computing TCP''s Retransmission Timer', 'Paxson, Allman, Chu & Sargent (IETF)', 2011, 'https://www.rfc-editor.org/rfc/rfc6298', 'Defines RTO: the minimum one-second floor that makes a single lost packet so expensive.'),
  ('rfc5681', 'RFC', 'RFC 5681: TCP Congestion Control', 'Allman, Paxson & Blanton (IETF)', 2009, 'https://www.rfc-editor.org/rfc/rfc5681', 'Slow start, congestion avoidance and fast retransmit — why throughput collapses on loss.'),
  ('rfc9112', 'RFC', 'RFC 9112: HTTP/1.1', 'Fielding, Nottingham & Reschke (IETF)', 2022, 'https://www.rfc-editor.org/rfc/rfc9112#name-persistence', 'The persistence section: what a connection may be reused for and when it must be closed.'),
  ('rfc9113', 'RFC', 'RFC 9113: HTTP/2', 'Thomson & Benfield (IETF)', 2022, 'https://www.rfc-editor.org/rfc/rfc9113', 'Multiplexing removes application-level head-of-line blocking but not the TCP-level kind.'),
  ('rfc9000', 'RFC', 'RFC 9000: QUIC', 'Iyengar & Thomson (IETF)', 2021, 'https://www.rfc-editor.org/rfc/rfc9000', 'Per-stream delivery over UDP: the transport answer to head-of-line blocking.'),
  ('rfc8446', 'RFC', 'RFC 8446: TLS 1.3', 'Eric Rescorla (IETF)', 2018, 'https://www.rfc-editor.org/rfc/rfc8446', 'One round trip for a full handshake, zero for resumption — the numbers behind handshake cost.'),
  ('rfc1035', 'RFC', 'RFC 1035: Domain Names — Implementation and Specification', 'Paul Mockapetris (IETF)', 1987, 'https://www.rfc-editor.org/rfc/rfc1035', 'TTL semantics and resolver behaviour, which is where most surprising DNS latency comes from.'),
  ('pg-explain', 'DOCS', 'PostgreSQL: Using EXPLAIN', 'PostgreSQL Global Development Group', NULL, 'https://www.postgresql.org/docs/current/using-explain.html', 'How to read a plan, and why EXPLAIN (ANALYZE, BUFFERS) is the only version worth trusting.'),
  ('pg-mvcc', 'DOCS', 'PostgreSQL: Concurrency Control (MVCC)', 'PostgreSQL Global Development Group', NULL, 'https://www.postgresql.org/docs/current/mvcc.html', 'Snapshots, xmin horizons and the reason one idle transaction can bloat a whole table.'),
  ('pg-explicit-locking', 'DOCS', 'PostgreSQL: Explicit Locking', 'PostgreSQL Global Development Group', NULL, 'https://www.postgresql.org/docs/current/explicit-locking.html', 'The lock conflict matrix and the deadlock detector''s behaviour, stated precisely.'),
  ('pg-stat-statements', 'DOCS', 'PostgreSQL: pg_stat_statements', 'PostgreSQL Global Development Group', NULL, 'https://www.postgresql.org/docs/current/pgstatstatements.html', 'Per-statement totals, mean times and row counts: the first place to look for a regression.'),
  ('pg-hot-standby', 'DOCS', 'PostgreSQL: Hot Standby', 'PostgreSQL Global Development Group', NULL, 'https://www.postgresql.org/docs/current/hot-standby.html', 'Replay lag, conflicts and the trade-off between replica freshness and query cancellation.'),
  ('pgbouncer', 'DOCS', 'PgBouncer Features', 'PgBouncer maintainers', NULL, 'https://www.pgbouncer.org/features.html', 'Pooling modes and their constraints — transaction pooling is not a drop-in for session state.'),
  ('jvm-gc-tuning', 'DOCS', 'HotSpot Virtual Machine Garbage Collection Tuning Guide', 'Oracle', NULL, 'https://docs.oracle.com/en/java/javase/21/gctuning/index.html', 'Collector choices, pause-time goals and what allocation rate does to each of them.'),
  ('nodejs-event-loop', 'DOCS', 'The Node.js Event Loop', 'Node.js contributors', NULL, 'https://nodejs.org/en/learn/asynchronous-work/event-loop-timers-and-nexttick', 'Phase order and the cost of holding the loop — required reading before blaming the database.'),
  ('epoll-man', 'DOCS', 'epoll(7) — Linux manual page', 'Linux man-pages project', NULL, 'https://man7.org/linux/man-pages/man7/epoll.7.html', 'The readiness interface every async runtime sits on, level- versus edge-triggered.'),
  ('getrlimit-man', 'DOCS', 'getrlimit(2) — Linux manual page', 'Linux man-pages project', NULL, 'https://man7.org/linux/man-pages/man2/getrlimit.2.html', 'RLIMIT_NOFILE and friends: the ceilings that turn into EMFILE at the worst moment.'),
  ('cfs-bandwidth', 'DOCS', 'CFS Bandwidth Control', 'Linux kernel documentation', NULL, 'https://docs.kernel.org/scheduler/sched-bwc.html', 'Quota, period and throttled time — the mechanism behind container CPU throttling.'),
  ('cgroup-v2', 'DOCS', 'Control Group v2', 'Linux kernel documentation', NULL, 'https://docs.kernel.org/admin-guide/cgroup-v2.html', 'How CPU, memory and I/O are actually partitioned between tenants on one host.'),
  ('stripe-idempotency', 'DOCS', 'Idempotent Requests', 'Stripe', NULL, 'https://docs.stripe.com/api/idempotent_requests', 'A production idempotency contract: key scope, result caching and the 24-hour window.'),
  ('resilience4j-bulkhead', 'DOCS', 'Resilience4j: Bulkhead', 'Resilience4j maintainers', NULL, 'https://resilience4j.readme.io/docs/bulkhead', 'Semaphore and thread-pool isolation, with the configuration knobs that make it real.'),
  ('rails-querying', 'DOCS', 'Active Record Query Interface: Eager Loading', 'Ruby on Rails contributors', NULL, 'https://guides.rubyonrails.org/active_record_querying.html#eager-loading-associations', 'The ORM side of N+1: how lazy association loading produces a query per row.'),
  ('reactive-streams', 'SPEC', 'Reactive Streams Specification', 'Reactive Streams contributors', 2015, 'https://www.reactive-streams.org/', 'Demand-driven flow control: the formal version of ''the consumer sets the pace''.'),
  ('otel-semconv', 'SPEC', 'OpenTelemetry Semantic Conventions', 'OpenTelemetry Authors', NULL, 'https://opentelemetry.io/docs/specs/semconv/', 'The names the evidence cards use, so a signal means the same thing across stacks.')
ON CONFLICT (id) DO UPDATE SET
    kind = excluded.kind,
    title = excluded.title,
    author = excluded.author,
    year = excluded.year,
    url = excluded.url,
    note = excluded.note,
    updated_at = now();

INSERT INTO public.evidence (id, concept_id, kind, trend, signal, what_you_see, where_to_look, why_it_matters, false_positive) VALUES
  ('ev-n1-trace', 'n-plus-one', 'TRACE', 'UP', 'db.statement span count per request', 'Dozens of near-identical child spans under one request span, each a few milliseconds, each selecting a single row by id.', 'A single slow trace in your tracing UI, sorted by span count rather than duration.', 'Latency scales with the number of rows rendered, so the endpoint degrades silently as data grows rather than when traffic grows.', 'A legitimate batch job can also issue many statements; check whether the statements differ only by a bound parameter.'),
  ('ev-n1-metric', 'n-plus-one', 'METRIC', 'UP', 'db.client.operation.duration (count) / http.server.request.duration (count)', 'Queries-per-request climbing from ~3 to ~60 after a release, while each query stays fast.', 'A ratio panel of database call count over request count, grouped by route.', 'The ratio isolates the N+1 from general traffic growth: the per-query time is innocent, the count is the bug.', 'Adding a legitimate feature to a page also raises the ratio; compare against the deploy marker.'),
  ('ev-unbounded-rows', 'unbounded-query', 'METRIC', 'UP', 'db.client.response.returned_rows', 'Row counts for one query id creeping from hundreds to hundreds of thousands over weeks.', 'Database statement statistics (pg_stat_statements.rows / calls) trended over time.', 'An unbounded query is a time bomb: nothing changes in the code, the table simply grows past the point where the result fits comfortably in memory.', 'A reporting query legitimately returns large results; check whether the caller is a user-facing route.'),
  ('ev-unbounded-oom', 'unbounded-query', 'LOG', 'PRESENT', 'JavaScript heap out of memory / OOMKilled', 'The process dies during a request that worked yesterday, and the restart happens under normal traffic.', 'Container restart events and the last 200 log lines before exit code 137.', 'Out-of-memory at a stable request rate points at result size, not concurrency.', 'A memory leak produces the same crash; a leak grows between requests, an unbounded query spikes inside one.'),
  ('ev-pagination-size', 'missing-pagination', 'METRIC', 'UP', 'http.server.response.body.size', 'p99 response bodies measured in megabytes on a list endpoint while p50 is a few kilobytes.', 'Response-size histogram for the route, not averages — the average hides it.', 'Large responses cost serialisation CPU, bandwidth and client memory, and they make timeouts look random because only large accounts hit them.', 'An export endpoint is supposed to be large; separate exports from browse endpoints.'),
  ('ev-pagination-deep', 'missing-pagination', 'QUERY_PLAN', 'UP', 'EXPLAIN: Limit … Offset 50000', 'A plan that scans and discards fifty thousand rows before returning twenty.', 'EXPLAIN (ANALYZE, BUFFERS) on the deepest page your UI can reach.', 'Offset pagination gets slower the further a user pages, which is why complaints come from your most engaged users.', 'Shallow pages look fine; always test the deep page, not the first one.'),
  ('ev-fanout-trace', 'synchronous-fanout', 'TRACE', 'UP', 'span.kind=client children per request', 'A trace waterfall shaped like a comb: one parent, many sequential outbound calls, total time equal to their sum.', 'The widest trace for the route, with the critical path highlighted.', 'Sequential fan-out makes your availability the product of everyone else''s, and your latency their sum.', 'Parallel fan-out shows the same span count but overlapping bars; only the sequential shape is the problem.'),
  ('ev-fanout-dependency', 'synchronous-fanout', 'METRIC', 'UP', 'http.client.request.duration by peer.service', 'Your endpoint''s error rate tracking another service''s error rate exactly, with no lag.', 'A correlation panel of your route''s errors against each downstream dependency.', 'Perfect correlation with no lag means you are calling it inline on the request path.', 'A shared dependency (both of you calling the same database) produces correlation without a direct call.'),
  ('ev-alloc-profile', 'hot-path-allocation', 'PROFILE', 'UP', 'allocation profile bytes by call site', 'One request handler responsible for most of the allocated bytes, mostly short-lived strings and intermediate arrays.', 'A heap allocation profile (pprof alloc_space, async-profiler alloc, --cpu-prof) taken under load.', 'Allocation rate drives collection frequency, so this shows up as GC pauses in a part of the system that looks unrelated.', 'Allocation is cheap in most runtimes; only act if GC pause time is actually significant.'),
  ('ev-retry-log', 'retry-storm', 'LOG', 'UP', 'retry attempt=N of M', 'Retry log lines growing several times faster than incoming request lines.', 'A log rate panel filtered to the client library''s retry message, overlaid on request rate.', 'When retries grow faster than traffic, the client is amplifying an outage instead of riding it out.', 'A single flaky dependency can raise retries without a storm; check whether the amplification is accelerating.'),
  ('ev-retry-metric', 'retry-storm', 'METRIC', 'SPIKE', 'http.client.request.duration{http.request.resend_count>0}', 'Attempts per logical call jumping from 1.0 to 3.0 within one scrape interval, all at once.', 'Resend-count ratio broken down by client instance.', 'Lockstep means the clients share a trigger: one downstream blip plus one synchronised retry policy.', 'A deploy that changes retry configuration moves the baseline permanently rather than spiking it.'),
  ('ev-herd-spike', 'thundering-herd', 'METRIC', 'SPIKE', 'http.server.request.count at fixed offsets', 'Request spikes arriving at exact wall-clock boundaries — every minute, on the minute.', 'High-resolution request rate (5s buckets); the pattern disappears at 1-minute resolution.', 'Clock-aligned spikes mean clients are coordinating by accident, usually through a cron or a shared cache TTL.', 'A real traffic pattern can be periodic too; the giveaway is the sharpness of the edge.'),
  ('ev-herd-recovery', 'thundering-herd', 'LOG', 'SPIKE', 'connection established after reconnect', 'Every client reconnecting in the same second after a restart, saturating the service it just rejoined.', 'Connection-accept logs during the minute after a restart or failover.', 'Recovery is the most dangerous moment: the herd arrives exactly when the service is coldest.', 'A rolling restart also concentrates reconnects; stagger it before blaming the clients.'),
  ('ev-timeout-span', 'missing-timeout', 'TRACE', 'UP', 'span duration with no deadline attribute', 'Client spans that run for minutes and end in cancellation, not response.', 'Traces filtered to duration greater than your SLO, sorted descending.', 'A call with no timeout turns a slow dependency into a leaked worker — the request never fails, it just occupies capacity.', 'A streaming or long-poll endpoint is legitimately long-lived; exclude it by route.'),
  ('ev-timeout-threads', 'missing-timeout', 'METRIC', 'UP', 'in-flight requests vs. request rate', 'In-flight count rising while throughput stays flat or falls.', 'A concurrency gauge next to a throughput counter on the same panel.', 'By Little''s Law, concurrency equals rate times latency — flat rate with rising concurrency means work is parking, not finishing.', 'A deliberate concurrency increase (bigger pool) also raises the gauge; compare with configuration changes.'),
  ('ev-breaker-state', 'circuit-breaker', 'METRIC', 'PRESENT', 'circuit.breaker.state (closed/open/half_open)', 'A state timeline that opens within seconds of a dependency failing and probes back to closed afterwards.', 'A state gauge per breaker, as a discrete timeline rather than an average.', 'This is the evidence that protection actually engaged; a breaker nobody can see is a breaker nobody trusts.', 'A breaker that flaps between open and half-open every few seconds is misconfigured, not protective.'),
  ('ev-ratelimit-429', 'rate-limiting', 'METRIC', 'UP', 'http.server.request.count{http.response.status_code=429}', '429 responses concentrated on a handful of API keys while everyone else is unaffected.', 'Status-code breakdown grouped by client identity.', 'Rate limiting is only working if it is selective: broad 429s mean the limit is too low or the key is too coarse.', 'A shared gateway key makes many tenants look like one noisy client.'),
  ('ev-bulkhead-isolation', 'bulkhead', 'METRIC', 'FLAT', 'pool utilisation by partition', 'One partition pinned at 100% while the others stay at their normal level and keep serving.', 'Per-pool saturation panels on a single shared axis.', 'Containment is the whole point: the evidence of a working bulkhead is a flat line next to a saturated one.', 'Low overall traffic also produces flat lines; confirm the failing partition is genuinely saturated.'),
  ('ev-pool-metric', 'connection-pool-exhaustion', 'METRIC', 'UP', 'db.client.connection.pending_requests', 'Pending acquisitions climbing while connection usage sits exactly at the configured maximum.', 'Pool metrics from the driver: usage, idle, pending, all on one panel.', 'Usage pinned at max with a queue behind it is the unambiguous signature; latency is then pure queueing, not database work.', 'A pool that is merely busy shows usage at max with an empty queue — that is healthy saturation.'),
  ('ev-pool-wait', 'connection-pool-exhaustion', 'TRACE', 'UP', 'connection acquisition span duration', 'A long ''acquire connection'' span in front of a fast query span.', 'Trace detail for a slow request, looking at the gap before the database span starts.', 'It separates waiting for a connection from waiting for the database — two problems with opposite fixes.', 'Driver instrumentation sometimes folds acquisition into the query span, hiding the wait entirely.'),
  ('ev-pool-timeout-log', 'connection-pool-exhaustion', 'LOG', 'PRESENT', 'timeout acquiring connection from pool', 'Acquisition timeouts appearing in bursts, often right after a slow-query incident.', 'Application error logs filtered to the pool''s timeout message.', 'The log line names the real constraint, which is otherwise reported to users as a generic 500.', 'A pool configured with an unrealistically short acquire timeout produces these under normal load.'),
  ('ev-lock-counter', 'lock-contention', 'METRIC', 'UP', 'pg_locks where granted = false', 'A growing population of ungranted locks, all waiting on the same relation or row.', 'A periodic query over pg_locks joined to pg_stat_activity, grouped by relation.', 'It names the exact object everyone is queueing for, which turns a vague ''database is slow'' into a specific hot row.', 'Brief spikes during a migration or bulk load are expected; sustained growth is not.'),
  ('ev-lock-wait-log', 'lock-contention', 'LOG', 'PRESENT', 'process still waiting for ShareLock after 1000 ms', 'Lock-wait warnings naming a blocking process id and the statement it is running.', 'Database server log with log_lock_waits enabled.', 'It identifies the blocker, not just the victim — the victim is the one complaining, the blocker is the one to fix.', 'An administrative statement such as a long ALTER can block everything briefly and legitimately.'),
  ('ev-index-plan', 'missing-index', 'QUERY_PLAN', 'UP', 'EXPLAIN: Rows Removed by Filter', 'A plan node that reads a million rows and keeps twelve.', 'EXPLAIN (ANALYZE, BUFFERS) on the slowest statement from pg_stat_statements.', 'The ratio of rows read to rows returned is the cleanest statement of wasted work in the whole system.', 'On a small table a sequential scan is correct and cheaper than an index; the ratio only matters at scale.'),
  ('ev-index-seqscan', 'missing-index', 'METRIC', 'UP', 'pg_stat_user_tables.seq_scan vs idx_scan', 'A large table whose sequential-scan counter rises steadily while its index-scan counter stays near zero.', 'Table-level statistics sorted by seq_tup_read.', 'It finds missing indexes across the whole database at once, instead of one slow query at a time.', 'Append-only tables scanned by analytics jobs will always look like this; check who is querying.'),
  ('ev-scan-plan', 'full-table-scan', 'QUERY_PLAN', 'PRESENT', 'EXPLAIN: Seq Scan on large_table', 'A sequential scan under a selective filter, with the estimated and actual row counts far apart.', 'EXPLAIN ANALYZE, comparing the estimate in parentheses with the actual rows.', 'A bad estimate usually means stale statistics, which is a different fix from adding an index.', 'A scan chosen for a query that genuinely touches most of the table is the right plan.'),
  ('ev-scan-io', 'full-table-scan', 'OS_COUNTER', 'UP', 'disk read throughput (MB/s) on the database host', 'Read throughput saturating the volume''s limit while CPU stays moderate.', 'Host or volume I/O metrics on the database instance.', 'It shows the scan is actually leaving the page cache and hitting storage, which is the difference between slow and catastrophic.', 'A backup, a vacuum or a replica rebuild produces the same read profile.'),
  ('ev-longtx-age', 'long-transaction', 'METRIC', 'UP', 'max(now() - xact_start)', 'A transaction age that keeps climbing — minutes, then hours — usually from one connection.', 'pg_stat_activity, sorted by transaction start time.', 'Long transactions hold snapshots that block vacuum, so a single forgotten BEGIN slowly degrades the whole database.', 'A legitimate long-running migration or analytical query also shows up; check the statement text.'),
  ('ev-longtx-idle', 'long-transaction', 'LOG', 'PRESENT', 'idle in transaction', 'Connections sitting in ''idle in transaction'' for minutes with no statement running.', 'pg_stat_activity.state, or the server log with log_min_duration_statement set.', 'Idle-in-transaction means the application opened a transaction and then went off to do something else — usually an HTTP call.', 'Interactive database sessions from a human are harmless; filter by application_name.'),
  ('ev-deadlock-log', 'deadlock', 'LOG', 'PRESENT', 'deadlock detected / Process A waits for … Process B waits for', 'A deadlock report naming two processes and the exact statements that formed the cycle.', 'Database server log; deadlocks are always logged with the full wait graph.', 'The wait graph tells you the lock ordering to change; no other signal gives you the cycle itself.', 'A single isolated deadlock under heavy concurrency can be normal; the rate is what matters.'),
  ('ev-deadlock-rate', 'deadlock', 'METRIC', 'UP', 'pg_stat_database.deadlocks', 'A deadlock counter that increments every few minutes instead of every few weeks.', 'Database-wide statistics, as a rate rather than a total.', 'A rising rate means a code path is acquiring locks in inconsistent order, and it will get worse with traffic.', 'A batch job that runs hourly can concentrate deadlocks into predictable windows.'),
  ('ev-replag-seconds', 'replication-lag', 'METRIC', 'UP', 'pg_last_xact_replay_timestamp lag in seconds', 'Replica lag growing during write bursts and taking minutes to recover afterwards.', 'Per-replica lag panels, with write throughput on the same chart.', 'Lag is the window during which reads are wrong; its shape tells you whether the replica is bandwidth-bound or apply-bound.', 'A paused or disconnected replica reports enormous lag that is a connectivity problem, not a throughput one.'),
  ('ev-replag-readback', 'replication-lag', 'LOG', 'PRESENT', 'record not found immediately after create', 'Not-found errors on a resource the user just created, resolving on refresh.', 'Application error logs correlated with the replica lag panel.', 'This is lag expressed as a user-visible bug, and it is the fastest way to convince a team the lag is real.', 'A genuine race between two services can look identical; check whether the read hit a replica.'),
  ('ev-plan-regression', 'query-plan-regression', 'QUERY_PLAN', 'PRESENT', 'plan node change for a stable query id', 'The same query id switching from Index Scan to Bitmap Heap Scan, with no code change.', 'Captured plans before and after the slowdown, diffed node by node.', 'It proves the query did not change — the planner''s mind did, usually because statistics or parameters changed.', 'A schema change deployed at the same time can be the real cause; check migration history.'),
  ('ev-plan-steptime', 'query-plan-regression', 'METRIC', 'UP', 'pg_stat_statements.mean_exec_time', 'A step change in mean execution time for one query id — flat, then suddenly ten times higher, then flat again.', 'Per-statement mean time trended, with ANALYZE and deploy markers overlaid.', 'Step changes point at planning; gradual rises point at data growth. The shape distinguishes them.', 'A change in parameter distribution (one huge tenant) produces the same step without any plan change.'),
  ('ev-writeamp-wal', 'write-amplification', 'METRIC', 'UP', 'WAL bytes written per logical row written', 'Ten kilobytes of write-ahead log for a hundred-byte update.', 'WAL generation rate divided by application write rate.', 'It quantifies how much hidden work each logical write creates — full-page images, index maintenance, replication traffic.', 'The first write to a page after a checkpoint always logs the full page; measure across a checkpoint cycle.'),
  ('ev-stampede-origin', 'cache-stampede', 'METRIC', 'SPIKE', 'origin request rate at cache expiry', 'A vertical spike in backend requests at the exact second a popular key expires, then silence.', 'Backend request rate at 1-second resolution, aligned with cache TTL boundaries.', 'The spike is instantaneous and periodic — unmistakable once you look at the right resolution.', 'A scheduled cache warm-up produces a similar spike on purpose.'),
  ('ev-stampede-dup', 'cache-stampede', 'TRACE', 'UP', 'identical cache miss spans in flight', 'Hundreds of concurrent traces, all missing the same key, all recomputing the same value.', 'Traces filtered to the miss path, grouped by cache key.', 'Seeing the same key in hundreds of simultaneous traces is the difference between ''the cache is cold'' and ''the cache is stampeding''.', 'A cold start after a deploy produces many misses across many different keys, not one key.'),
  ('ev-coldcache-ratio', 'cold-cache', 'METRIC', 'DOWN', 'cache hit ratio', 'Hit ratio collapsing to near zero at a deploy marker and climbing back over several minutes.', 'Hit-ratio panel with deployment annotations.', 'The recovery curve tells you how long the service is fragile after every restart — that is your real deploy risk window.', 'A cache key format change empties the cache logically without any restart.'),
  ('ev-hotkey-ops', 'hot-key', 'METRIC', 'UP', 'ops per key / per shard', 'One key or shard taking a large share of all operations while the rest of the cluster idles.', 'Per-shard operation rate, plus the cache''s own hot-key report (redis-cli --hotkeys, MONITOR sampling).', 'Sharding only helps if load spreads; a single hot key turns a distributed cache back into one server.', 'A monitoring agent polling one key can look like application traffic.'),
  ('ev-hotkey-cpu', 'hot-key', 'OS_COUNTER', 'UP', 'single-core CPU on one cache node', 'One node''s CPU at 100% while its siblings sit at 10%, with similar memory usage.', 'Per-node CPU across the cache cluster on a shared axis.', 'Cache servers are usually single-threaded per shard, so a hot key shows up as one saturated core, not high average CPU.', 'An unbalanced shard map causes the same asymmetry without any single hot key.'),
  ('ev-invalidation-stale', 'cache-invalidation', 'LOG', 'PRESENT', 'stale read detected / version mismatch', 'Reads returning a version older than the last write, clustered just after writes.', 'Application-level version checks logged on read, compared against write timestamps.', 'Staleness is invisible in cache metrics — hit ratio looks great while the answers are wrong.', 'Clock skew between writer and reader can fake a version mismatch.'),
  ('ev-gc-metric', 'gc-pause', 'METRIC', 'SPIKE', 'process.runtime.gc.duration', 'Pause spikes that line up exactly with p99 latency spikes, while p50 stays flat.', 'GC pause histogram overlaid on request latency percentiles.', 'If the two spike together, latency is a runtime problem, and no amount of query tuning will fix it.', 'A stop-the-world pause from a heap dump or a profiler attach looks identical.'),
  ('ev-gc-frequency', 'gc-pause', 'METRIC', 'UP', 'collections per minute by generation', 'Young collections every few hundred milliseconds, old collections several times a minute.', 'Collection counters split by generation.', 'Frequency separates allocation pressure (young) from a sizing or leak problem (old) — different fixes entirely.', 'A deliberately small heap trades frequent cheap collections for memory; that can be fine.'),
  ('ev-heap-pressure', 'heap-pressure', 'METRIC', 'UP', 'heap used after full collection', 'The floor of the sawtooth rising release after release, even though the peaks look unchanged.', 'Heap usage over hours, reading the post-collection minimum rather than the peak.', 'Live-set size is the honest number; peak heap tells you about allocation, not about what the process actually retains.', 'A cache that legitimately fills to a bounded size raises the floor once and then holds.'),
  ('ev-heap-rss', 'heap-pressure', 'OS_COUNTER', 'UP', 'container memory.current vs memory.max', 'Resident memory approaching the container limit while the runtime heap reports plenty of headroom.', 'cgroup memory statistics next to runtime heap metrics.', 'Off-heap memory — buffers, native libraries, thread stacks — is invisible to the runtime and is what actually gets you killed.', 'Page cache counted inside the cgroup can inflate the number without real pressure.'),
  ('ev-leak-profile', 'memory-leak', 'PROFILE', 'UP', 'heap snapshot retained size by type', 'One type''s retained size growing across three snapshots taken an hour apart, with a clear dominator path.', 'Comparative heap snapshots, sorted by retained size delta.', 'The dominator path names the object that is holding the garbage alive — that is the actual bug, not the leaked object.', 'A deliberately unbounded in-memory cache is a leak by any other name; decide which one you have.'),
  ('ev-leak-restart', 'memory-leak', 'LOG', 'PRESENT', 'OOMKilled / exit code 137 on a fixed cadence', 'Restarts arriving at regular intervals, the interval shortening as traffic grows.', 'Container restart history across all replicas.', 'A predictable sawtooth of restarts is the signature of a leak; a crash under peak load is usually something else.', 'A memory limit set below real working-set size produces regular kills without any leak.'),
  ('ev-threadpool-queue', 'thread-pool-starvation', 'METRIC', 'UP', 'executor queue depth', 'Queue depth growing while active threads sit at maximum and CPU stays low.', 'Executor metrics: active, queued, completed, on one panel.', 'Max threads plus idle CPU means the threads are blocked on I/O, not doing work — adding threads buys a little time, fixing the blocking call fixes it.', 'A deliberately bounded pool in front of a slow dependency will queue by design.'),
  ('ev-threadpool-wait', 'thread-pool-starvation', 'TRACE', 'UP', 'queue wait time before handler span', 'A long gap between request receipt and the first application span.', 'Trace timeline for a slow request, measuring the gap at the start.', 'It splits total latency into waiting-to-start and actually-running, which is the first fork in every latency investigation.', 'Clock skew between the receiving proxy and the application can fabricate a gap.'),
  ('ev-eventloop-lag', 'event-loop-blocking', 'METRIC', 'UP', 'event loop lag / utilisation', 'Loop lag jumping to hundreds of milliseconds while CPU is not saturated.', 'Runtime event-loop metrics at high resolution.', 'In a single-threaded runtime, loop lag is latency for every concurrent request — one slow synchronous call taxes all of them.', 'A long garbage collection pause registers as loop lag too.'),
  ('ev-eventloop-profile', 'event-loop-blocking', 'PROFILE', 'PRESENT', 'CPU profile: long synchronous frame', 'A single frame — JSON parsing, crypto, a big sort — holding the stack for tens of milliseconds.', 'A CPU profile captured during a lag spike, read as a flame graph.', 'It names the exact function to make asynchronous or move off the main thread.', 'Profilers attribute inlined native work oddly; verify with a second capture.'),
  ('ev-asyncio-density', 'async-io', 'METRIC', 'UP', 'in-flight requests per OS thread', 'Thousands of concurrent connections served by a handful of threads, with memory flat.', 'Concurrency gauge divided by the runtime''s thread count.', 'High density is the entire payoff of async I/O: if it is near one, you have paid the complexity and kept the thread-per-request cost.', 'Idle keep-alive connections inflate the numerator without representing real concurrency.'),
  ('ev-asyncio-offcpu', 'async-io', 'PROFILE', 'PRESENT', 'off-CPU profile: threads parked in epoll_wait / kqueue', 'Worker threads waiting in the event notification syscall rather than inside a blocking read.', 'An off-CPU or wall-clock profile captured under load.', 'It proves the I/O is really non-blocking; one accidental synchronous call shows up here as a thread parked in read() instead.', 'Thread pools used for file I/O legitimately block, even in a fully async runtime.'),
  ('ev-retx-packet', 'tcp-retransmits', 'PACKET', 'PRESENT', 'TCP retransmission / duplicate ACK', 'The same segment sent again after a retransmission timeout, often in bursts.', 'A short packet capture on the sending host, filtered with tcp.analysis.retransmission.', 'Retransmits explain latency that no application metric can account for — the request simply was not delivered.', 'Capture-point artefacts (offload, mirrored ports) can show phantom retransmits.'),
  ('ev-retx-os', 'tcp-retransmits', 'OS_COUNTER', 'UP', 'netstat -s TcpRetransSegs / TcpExtTCPLostRetransmit', 'Retransmitted segments rising as a fraction of segments sent, on one host or one path.', 'Kernel network statistics sampled as a rate, compared between hosts.', 'It is cheap to collect everywhere, so it tells you whether the loss is one host, one availability zone, or the whole path.', 'A noisy client network inflates the counter for traffic you do not control.'),
  ('ev-holb-queue', 'head-of-line-blocking', 'METRIC', 'UP', 'time to first byte with flat server processing time', 'Client-side latency rising while server-side handler time stays flat.', 'Client and server latency for the same call, plotted together.', 'A gap that grows between client and server time is queueing somewhere in between — connection, proxy or kernel.', 'Clock skew between client and server can manufacture or hide the gap.'),
  ('ev-dns-span', 'dns-latency', 'TRACE', 'SPIKE', 'DNS resolution span duration', 'Occasional resolution spans of exactly five seconds — the classic resolver timeout — inside otherwise fast requests.', 'Traces filtered to the client call, with resolution instrumented separately.', 'Round numbers like 5s are timeouts, not work; they identify a retry at the resolver rather than a slow network.', 'Many clients cache DNS internally, so the spans appear only on cold connections.'),
  ('ev-dns-log', 'dns-latency', 'LOG', 'PRESENT', 'EAI_AGAIN / temporary failure in name resolution', 'Resolution failures bursting across many pods at once.', 'Application error logs, grouped by node rather than by service.', 'Clustering by node distinguishes a broken local resolver cache from an upstream DNS outage.', 'A misspelled hostname in a new release produces the same error permanently, not in bursts.'),
  ('ev-churn-timewait', 'connection-churn', 'OS_COUNTER', 'UP', 'sockets in TIME_WAIT', 'Tens of thousands of sockets in TIME_WAIT on a client host, with ephemeral ports running out.', 'ss -s or netstat -an summarised by state.', 'Each new connection costs a handshake and a port; churn turns a cheap call into an expensive one and eventually fails outright.', 'A load generator legitimately opens short-lived connections; compare against production clients.'),
  ('ev-churn-rate', 'connection-churn', 'METRIC', 'UP', 'new connections per second vs requests per second', 'A connection-to-request ratio near one, where it should be near zero.', 'Connection-accept rate over request rate at the server or proxy.', 'The ratio is the direct measure of connection reuse; anything near one means keep-alive is not working.', 'A proxy terminating and re-establishing connections can shift the ratio without any client change.'),
  ('ev-keepalive-reuse', 'keep-alive', 'METRIC', 'UP', 'connection reuse ratio', 'Requests per connection in the hundreds, with a stable pool of established sockets.', 'Client pool metrics: created, reused, closed.', 'High reuse is the evidence that handshake cost has actually been eliminated rather than merely hidden.', 'A long-lived connection to a dead peer also looks reused until the first failure.'),
  ('ev-tls-span', 'tls-handshake-cost', 'TRACE', 'UP', 'TLS handshake span duration', 'Twenty to one hundred milliseconds of handshake in front of a two-millisecond call, on the first request only.', 'A trace of a cold request, with connect and TLS phases instrumented.', 'Handshake cost is paid per connection, so it is invisible in averages and dominant in cold-start and health-check traffic.', 'Session resumption makes subsequent handshakes much cheaper; measure cold and warm separately.'),
  ('ev-tls-cpu', 'tls-handshake-cost', 'OS_COUNTER', 'UP', 'CPU time in crypto routines', 'A measurable share of total CPU in asymmetric crypto on a service with modest traffic.', 'A CPU profile on the terminating proxy, grouped by library.', 'Handshakes are the expensive part of TLS; bulk encryption is nearly free. This separates the two.', 'Hardware acceleration can make the cost disappear from profiles while remaining in latency.'),
  ('ev-throttle-os', 'cpu-throttling', 'OS_COUNTER', 'UP', 'cgroup cpu.stat nr_throttled / throttled_usec', 'Throttled periods accumulating while average CPU utilisation looks comfortable, around 60%.', 'cgroup v2 cpu.stat on the node, per container.', 'Average utilisation hides throttling completely: the quota is enforced per 100 ms period, so a bursty service is throttled at low averages.', 'A very low CPU request with bursty traffic will always throttle a little; look at the proportion of periods affected.'),
  ('ev-throttle-latency', 'cpu-throttling', 'METRIC', 'UP', 'p99 latency correlated with throttled periods', 'Latency steps that line up exactly with throttling, in 100-millisecond quanta.', 'Throttled time and latency percentiles on one chart.', 'The quantised shape is distinctive — it proves the delay is quota enforcement rather than contention.', 'A noisy neighbour produces similar latency without any throttling counter movement.'),
  ('ev-ctxsw-rate', 'context-switching', 'OS_COUNTER', 'UP', 'context switches per second (voluntary vs involuntary)', 'Hundreds of thousands of switches per second, mostly involuntary, with system CPU time rising.', 'vmstat or /proc/stat, split into voluntary and involuntary.', 'Involuntary switches mean too many runnable threads for the cores available — the fix is fewer threads, not more.', 'Voluntary switches are just I/O waits and are entirely normal.'),
  ('ev-ctxsw-runqueue', 'context-switching', 'OS_COUNTER', 'UP', 'run queue length vs core count', 'A run queue several times longer than the number of available cores, sustained.', 'Load average and run queue depth, compared with the container''s CPU allocation.', 'Queue length relative to cores is the honest saturation measure; load average alone is nearly meaningless in containers.', 'Processes in uninterruptible I/O sleep inflate load average on Linux without consuming CPU.'),
  ('ev-fd-log', 'fd-exhaustion', 'LOG', 'PRESENT', 'EMFILE: too many open files', 'Accept or open calls failing while the process keeps running and serving existing connections.', 'Application error logs; the failure is usually in the accept loop.', 'The error names a hard limit, so it is one of the few log lines that tells you the fix directly.', 'A low ulimit inherited from the container image causes this at trivial concurrency.'),
  ('ev-fd-counter', 'fd-exhaustion', 'OS_COUNTER', 'UP', 'open file descriptors vs RLIMIT_NOFILE', 'Descriptor count climbing monotonically and never returning to baseline between traffic peaks.', '/proc/<pid>/fd count against the process limit, trended.', 'Monotonic growth distinguishes a descriptor leak from a legitimately busy server.', 'A connection pool that is warming up grows once and then plateaus.'),
  ('ev-pagecache-faults', 'page-cache-thrashing', 'OS_COUNTER', 'UP', 'major page faults per second', 'Major faults rising sharply while minor faults stay normal, with disk reads following.', '/proc/vmstat pgmajfault, next to block-device read throughput.', 'Major faults mean the working set no longer fits in memory, which turns memory-speed access into disk-speed access.', 'The first run after a restart always faults as the cache fills.'),
  ('ev-pagecache-io', 'page-cache-thrashing', 'METRIC', 'UP', 'read IOPS with stable logical read rate', 'Physical reads climbing while the application''s logical read rate is unchanged.', 'Database buffer-cache hit ratio alongside device-level IOPS.', 'Constant logical reads with rising physical reads is caching failure, not increased demand.', 'A competing process on the same host can evict your cache without any change in your workload.'),
  ('ev-noisy-steal', 'noisy-neighbor', 'OS_COUNTER', 'UP', 'CPU steal time', 'Steal time of several percent on one instance and near zero on its identical siblings.', 'Per-instance CPU breakdown including steal, compared across the fleet.', 'Steal is time the hypervisor gave to someone else — proof the problem is outside your process.', 'Burstable instance types that have exhausted their credits show similar symptoms through a different mechanism.'),
  ('ev-noisy-variance', 'noisy-neighbor', 'METRIC', 'UP', 'p99 latency variance across identical replicas', 'One replica consistently slower than the rest while serving identical traffic and running identical code.', 'Per-replica latency percentiles on a single panel.', 'Identical code plus identical traffic plus different latency means the difference is the host, not the software.', 'Uneven load balancing produces the same picture; check per-replica request rate first.'),
  ('ev-queue-depth', 'queue-buildup', 'METRIC', 'UP', 'queue depth and oldest message age', 'Depth rising steadily and the oldest message ageing past the point where processing it is still useful.', 'Broker metrics: depth, consumer lag, oldest-message age.', 'Age matters more than depth: a deep queue that drains fast is fine, a shallow queue of stale work is not.', 'A deliberate buffer in front of a batch consumer is supposed to be deep.'),
  ('ev-queue-ratio', 'queue-buildup', 'METRIC', 'DOWN', 'consumer throughput / producer throughput', 'A ratio below one, sustained, with no recovery during traffic troughs.', 'Producer and consumer rates on the same panel.', 'A ratio below one for long enough has only one ending; the trough is where you find out whether it is temporary.', 'A consumer restart causes a brief dip that recovers on its own.'),
  ('ev-tail-ratio', 'tail-latency', 'METRIC', 'UP', 'p99 / p50 ratio', 'A ratio climbing from 3 to 30 while the median does not move at all.', 'Latency percentiles as a ratio panel, not as separate lines.', 'The ratio isolates variance from slowness; it is the single best early warning of saturation anywhere in the stack.', 'Mixing fast and slow endpoints in one aggregate produces a high ratio with no underlying problem.'),
  ('ev-tail-slowest', 'tail-latency', 'TRACE', 'PRESENT', 'slowest traces grouped by waiting phase', 'The slowest 1% of traces sharing one phase — queueing, a lock, a retry — while the rest of the span tree is normal.', 'Trace search sorted by duration, grouped by the dominant span.', 'Tail latency almost always has one cause; the fastest way to find it is to read the tail itself rather than the average.', 'Sampling often discards slow traces; make sure tail-based sampling is enabled before concluding anything.'),
  ('ev-cascade-spread', 'cascading-failure', 'METRIC', 'UP', 'error rate by service over time', 'Errors appearing in one service and then in its callers, tens of seconds apart, spreading outward.', 'A service-level error-rate heatmap ordered by dependency depth.', 'The time offsets reveal the direction of propagation, which tells you where the origin is rather than where the noise is loudest.', 'A shared dependency failing makes everything fail simultaneously, with no offset — that is a different failure mode.'),
  ('ev-cascade-saturation', 'cascading-failure', 'METRIC', 'UP', 'concurrency saturation across services', 'Thread pools and connection pools reaching their limits one after another, in dependency order.', 'Saturation panels for every service, stacked in call order.', 'Cascades propagate through resource exhaustion, so saturation spreads before errors do — it is the earlier signal.', 'A coordinated deploy can saturate several services at once without any cascade.'),
  ('ev-shed-count', 'load-shedding', 'METRIC', 'UP', 'shed requests / 503 with Retry-After', 'A plateau of shed requests while accepted requests hold a steady, serviceable rate.', 'Accepted and shed counters on one stacked panel.', 'Shedding is working when the accepted line stays flat and fast; if accepted latency rises too, the threshold is set too high.', 'A proxy returning 503 for its own reasons looks the same from outside.'),
  ('ev-backpressure-block', 'backpressure', 'METRIC', 'UP', 'producer blocked time / stream pause events', 'Producers spending measurable time blocked, with queue depth bounded and stable.', 'Stream or channel instrumentation on the producing side.', 'Blocked producers with a bounded queue is backpressure working; unbounded growth with happy producers is backpressure missing.', 'A slow producer that is never blocked may simply be upstream-limited.'),
  ('ev-hedge-duplicates', 'hedged-requests', 'METRIC', 'UP', 'duplicate request ratio', 'A few percent of requests sent twice, with the p99 dropping and the p50 unchanged.', 'Hedge counter over total requests, next to latency percentiles.', 'Hedging is only worth it if the extra load is small and the tail actually improves — both numbers have to be on the same screen.', 'A hedge rate above ten percent usually means the trigger threshold is below the service''s normal p95.'),
  ('ev-backoff-spacing', 'exponential-backoff', 'LOG', 'PRESENT', 'retry delays with jitter', 'Retry intervals spreading out — 100 ms, 230 ms, 870 ms — and differing between clients.', 'Client retry logs from several instances, compared.', 'Identical intervals across clients mean the jitter is missing, which is what turns a retry policy into a synchronised herd.', 'Log timestamp granularity can hide small amounts of jitter.'),
  ('ev-idempotency-dupes', 'idempotency-key', 'METRIC', 'FLAT', 'duplicate-key hits on write endpoints', 'A steady trickle of requests matching a previously seen key and returning the original result.', 'Idempotency-store hit counter, next to the client retry rate.', 'It shows retries are being absorbed safely — the same evidence proves both that clients retry and that you survive it.', 'A key generated per attempt instead of per logical operation produces zero hits while looking correct.'),
  ('ev-pooler-saturation', 'connection-pooler', 'METRIC', 'FLAT', 'server-side connections vs client-side connections', 'Thousands of client connections multiplexed onto a few dozen database connections.', 'Pooler statistics (pgbouncer SHOW POOLS) next to database connection count.', 'The ratio is the pooler''s entire value proposition; if it approaches one, the pooler is a proxy and nothing more.', 'Session-mode pooling cannot multiplex, so the ratio stays near one by design.'),
  ('ev-coalescing-origin', 'request-coalescing', 'METRIC', 'DOWN', 'origin requests per cache miss', 'A single origin request serving hundreds of waiting callers for the same key.', 'Miss count against origin fetch count for the same cache.', 'A ratio far below one is proof the single-flight lock is working, and it is the direct antidote to the stampede spike.', 'Low concurrency makes the ratio look like one even when coalescing works correctly.')
ON CONFLICT (id) DO UPDATE SET
    concept_id = excluded.concept_id,
    kind = excluded.kind,
    trend = excluded.trend,
    signal = excluded.signal,
    what_you_see = excluded.what_you_see,
    where_to_look = excluded.where_to_look,
    why_it_matters = excluded.why_it_matters,
    false_positive = excluded.false_positive,
    updated_at = now();

INSERT INTO public.concept_sources (concept_id, source_id, relevance) VALUES
  ('n-plus-one', 'rails-querying', 'The eager-loading section shows the exact lazy-association pattern that generates the extra queries.'),
  ('n-plus-one', 'otel-semconv', 'Database client span conventions give you the per-request query count without custom instrumentation.'),
  ('unbounded-query', 'use-the-index-luke', 'Explains why a query that returns everything cannot be fixed with an index.'),
  ('unbounded-query', 'pg-stat-statements', 'The rows/calls ratio is the cheapest way to find result sets that grew over time.'),
  ('missing-pagination', 'no-offset', 'Makes the case for keyset pagination with the cost curve of deep OFFSET.'),
  ('missing-pagination', 'use-the-index-luke', 'Covers the index support a keyset predicate needs to stay fast.'),
  ('hot-path-allocation', 'systems-performance', 'Chapter 7 connects allocation rate to memory bandwidth and collector pressure.'),
  ('hot-path-allocation', 'jvm-gc-tuning', 'Allocation rate is the input variable for every pause-time goal in the guide.'),
  ('synchronous-fanout', 'tail-at-scale', 'Quantifies how a 1-in-100 slow response becomes a 1-in-2 slow request under fan-out.'),
  ('synchronous-fanout', 'release-it', 'The integration-point chapter on how one slow dependency blocks a whole request path.'),
  ('retry-storm', 'backoff-jitter', 'Simulations showing that backoff alone still leaves clients synchronised.'),
  ('retry-storm', 'timeouts-retries', 'Retry budgets and client-side token buckets, with the failure they prevent.'),
  ('retry-storm', 'metastable-failures', 'Retries are the classic sustaining effect that keeps a system down after the trigger is gone.'),
  ('thundering-herd', 'fail-at-scale', 'Describes the herd that forms the moment a shared dependency recovers.'),
  ('thundering-herd', 'memcache-fb', 'Leases exist specifically to stop a herd of clients regenerating the same value.'),
  ('missing-timeout', 'timeouts-retries', 'How to pick a timeout from the latency distribution instead of a round number.'),
  ('missing-timeout', 'release-it', 'The timeout pattern and the resource leak that an unbounded wait causes.'),
  ('exponential-backoff', 'backoff-jitter', 'The jitter variants compared, including why full jitter usually wins.'),
  ('exponential-backoff', 'timeouts-retries', 'Places backoff inside a complete retry policy rather than treating it as the whole answer.'),
  ('circuit-breaker', 'fowler-circuit-breaker', 'The three states and the half-open probe, in the clearest short form.'),
  ('circuit-breaker', 'release-it', 'Where the breaker belongs in a system and what it must do with the rejected call.'),
  ('rate-limiting', 'stripe-rate-limiters', 'Four limiter types deployed together, with the reasoning for each.'),
  ('rate-limiting', 'builders-fairness', 'Per-tenant quotas as the fairness mechanism rather than a global ceiling.'),
  ('idempotency-key', 'stripe-idempotency', 'A real contract: key scope, stored response, and the retry window.'),
  ('idempotency-key', 'ddia', 'Chapter 11 on exactly-once semantics being built from deduplication, not from magic.'),
  ('bulkhead', 'resilience4j-bulkhead', 'Semaphore versus thread-pool isolation with concrete configuration.'),
  ('bulkhead', 'release-it', 'The bulkhead pattern as damage containment, drawn from ship design.'),
  ('connection-pool-exhaustion', 'littles-law', 'Pool size is λ×W: the law tells you the number before you guess it.'),
  ('connection-pool-exhaustion', 'pgbouncer', 'What happens on the database side when the application pool is already too large.'),
  ('lock-contention', 'pg-explicit-locking', 'The conflict matrix that decides which statement waits for which.'),
  ('lock-contention', 'ddia', 'Chapter 7 on isolation levels and the concurrency they trade away.'),
  ('missing-index', 'use-the-index-luke', 'Index selection from the query''s perspective, including composite column order.'),
  ('missing-index', 'pg-explain', 'How a sequential scan appears in the plan and what the row estimate tells you.'),
  ('full-table-scan', 'pg-explain', 'Reading scan nodes, row estimates and buffer counts in a real plan.'),
  ('full-table-scan', 'use-the-index-luke', 'When a full scan is correct and when it is a missing index in disguise.'),
  ('long-transaction', 'pg-mvcc', 'Snapshot visibility and the xmin horizon that an idle transaction pins.'),
  ('long-transaction', 'pg-explicit-locking', 'Locks held to commit: why transaction length is lock duration.'),
  ('deadlock', 'pg-explicit-locking', 'Deadlock detection, the timeout that triggers it, and consistent lock ordering.'),
  ('deadlock', 'ddia', 'Chapter 7 on deadlock as a property of concurrent access patterns, not of bad luck.'),
  ('replication-lag', 'ddia', 'Chapter 5 on read-your-writes, monotonic reads and the anomalies lag produces.'),
  ('replication-lag', 'pg-hot-standby', 'Replay lag measurement and the conflicts that make a replica cancel queries.'),
  ('connection-pooler', 'pgbouncer', 'Pooling modes and the session-state constraints each one imposes.'),
  ('connection-pooler', 'littles-law', 'Sizing the pool behind the pooler with the same arithmetic, one layer down.'),
  ('query-plan-regression', 'pg-explain', 'Comparing two plans for the same statement, which is the whole diagnosis.'),
  ('query-plan-regression', 'pg-stat-statements', 'Mean time per statement over time is how a regression announces itself.'),
  ('write-amplification', 'lsm-tree', 'The original analysis of deferring write cost into compaction.'),
  ('write-amplification', 'ddia', 'Chapter 3 compares B-tree and LSM write amplification with their trade-offs.'),
  ('cache-stampede', 'memcache-fb', 'Leases as the production answer to many clients missing the same key at once.'),
  ('cache-stampede', 'caching-strategies', 'The bimodal behaviour a cache adds, and the failure it hides until expiry.'),
  ('request-coalescing', 'memcache-fb', 'One regeneration per key while everyone else waits for the result.'),
  ('request-coalescing', 'caching-strategies', 'Where coalescing belongs relative to the cache and the origin.'),
  ('cold-cache', 'caching-strategies', 'Why a cold cache is a capacity problem, not a latency problem.'),
  ('cold-cache', 'sre-book', 'The overload chapter on recovery traffic exceeding steady-state capacity.'),
  ('hot-key', 'memcache-fb', 'Key-level hot spots and the replication tricks used to spread them.'),
  ('hot-key', 'builders-fairness', 'One tenant''s hot key as a fairness failure across a shared cache.'),
  ('cache-invalidation', 'caching-strategies', 'Invalidation strategies and the staleness each one accepts.'),
  ('cache-invalidation', 'ddia', 'Chapter 11 on derived data staying consistent with its source.'),
  ('gc-pause', 'jvm-gc-tuning', 'Collector-by-collector pause behaviour and the goals you can actually set.'),
  ('gc-pause', 'systems-performance', 'Measuring pauses from outside the runtime, where they look like latency.'),
  ('heap-pressure', 'jvm-gc-tuning', 'Heap sizing, promotion failures and the collector''s response to pressure.'),
  ('heap-pressure', 'systems-performance', 'Memory saturation signals at the OS level before the process dies.'),
  ('memory-leak', 'systems-performance', 'Chapter 7 separates a leak from growth and shows how to attribute both.'),
  ('memory-leak', 'jvm-gc-tuning', 'Why a leak shows up as rising post-collection live-set, not as allocation rate.'),
  ('thread-pool-starvation', 'littles-law', 'The thread count a given arrival rate and service time require.'),
  ('thread-pool-starvation', 'release-it', 'Blocked threads as the most common path to an unresponsive service.'),
  ('event-loop-blocking', 'nodejs-event-loop', 'Phase order and what holding the loop does to every pending callback.'),
  ('event-loop-blocking', 'systems-performance', 'Profiling the synchronous frame that is holding the stack.'),
  ('async-io', 'epoll-man', 'The readiness interface underneath every async runtime, level- versus edge-triggered.'),
  ('async-io', 'nodejs-event-loop', 'How readiness becomes callbacks, and which work still runs on a thread pool.'),
  ('tcp-retransmits', 'rfc6298', 'The retransmission timer and the minimum RTO that makes a lost packet expensive.'),
  ('tcp-retransmits', 'rfc5681', 'Fast retransmit, fast recovery and the congestion window response to loss.'),
  ('tcp-retransmits', 'systems-performance', 'Which counters to read, and the difference between retransmits and drops.'),
  ('head-of-line-blocking', 'rfc9113', 'HTTP/2 multiplexing removes the application-level form but not the transport one.'),
  ('head-of-line-blocking', 'rfc9000', 'QUIC''s per-stream delivery, the transport fix for the remaining case.'),
  ('head-of-line-blocking', 'hpbn', 'The protocol history that explains why six connections per origin ever made sense.'),
  ('dns-latency', 'rfc1035', 'TTL semantics and resolver behaviour, the source of most surprising lookup latency.'),
  ('dns-latency', 'hpbn', 'Where lookups sit in the connection timeline and what prefetching can remove.'),
  ('connection-churn', 'timewait-bernat', 'What TIME-WAIT actually costs and which sysctl advice is wrong.'),
  ('connection-churn', 'hpbn', 'Setup cost per connection, which is the reason churn matters at all.'),
  ('keep-alive', 'rfc9112', 'The persistence rules: what may be reused and when a connection must close.'),
  ('keep-alive', 'hpbn', 'Idle-timeout tuning across client, server and every proxy in between.'),
  ('tls-handshake-cost', 'rfc8446', 'One round trip for a full handshake, zero for resumption, with the caveats.'),
  ('tls-handshake-cost', 'hpbn', 'Handshake cost in real latency terms, including session resumption behaviour.'),
  ('cpu-throttling', 'cfs-bandwidth', 'Quota, period and throttled time — the exact mechanism and its counters.'),
  ('cpu-throttling', 'cgroup-v2', 'Where the limit is configured and how it interacts with the rest of the host.'),
  ('context-switching', 'systems-performance', 'Voluntary versus involuntary switches and what each one tells you.'),
  ('context-switching', 'use-method', 'Saturation as the signal that the run queue, not the CPU, is the problem.'),
  ('fd-exhaustion', 'getrlimit-man', 'The limits themselves, and which syscalls return EMFILE when you hit them.'),
  ('fd-exhaustion', 'epoll-man', 'Why an event-driven server holds so many descriptors at once.'),
  ('page-cache-thrashing', 'systems-performance', 'Chapter 8 on the file-system cache, hit ratios and the fall off the cliff.'),
  ('page-cache-thrashing', 'use-method', 'Memory saturation signals: scan rate and major faults before latency moves.'),
  ('noisy-neighbor', 'builders-fairness', 'Multi-tenant interference framed as a fairness problem with quota answers.'),
  ('noisy-neighbor', 'cgroup-v2', 'The isolation primitives available when fairness must be enforced on one host.'),
  ('cascading-failure', 'metastable-failures', 'The sustaining effect that keeps a system down after the trigger clears.'),
  ('cascading-failure', 'fail-at-scale', 'Real cascades and the controls that stopped them at Facebook scale.'),
  ('cascading-failure', 'sre-book', 'The addressing-cascading-failures chapter, including how to break the loop.'),
  ('load-shedding', 'builders-load-shedding', 'Why a fast rejection beats a slow success and where the decision belongs.'),
  ('load-shedding', 'sre-book', 'Criticality-aware shedding so the important traffic survives the cut.'),
  ('backpressure', 'reactive-streams', 'Demand-driven flow control specified precisely enough to implement.'),
  ('backpressure', 'builders-queue-backlogs', 'What happens when there is no backpressure: the queue absorbs it until it cannot.'),
  ('queue-buildup', 'builders-queue-backlogs', 'Backlogs that outlive the usefulness of their contents, and how to bound them.'),
  ('queue-buildup', 'littles-law', 'Wait time is queue length over throughput; the backlog predicts the latency.'),
  ('tail-latency', 'tail-at-scale', 'The paper that made p99 a design constraint rather than a reporting detail.'),
  ('tail-latency', 'sre-workbook', 'Turning percentile targets into SLOs you can actually operate against.'),
  ('tail-latency', 'otel-semconv', 'Histogram conventions so percentiles stay comparable across services.'),
  ('hedged-requests', 'tail-at-scale', 'Hedging and tied requests, with the measured effect on p99 and on load.'),
  ('hedged-requests', 'sre-workbook', 'The cost side: extra load in exchange for a shorter tail.')
ON CONFLICT (concept_id, source_id) DO UPDATE SET
    relevance = excluded.relevance,
    updated_at = now();

INSERT INTO public.symptoms (id, name, layer_id, description, signal, trend) VALUES
  ('p99-latency-up', 'API p99 latency up', 'api', 'The slow end of the distribution moved while the median barely did.', 'http.server.request.duration p99', 'UP'),
  ('error-rate-up', '5xx error rate climbing', 'api', 'Requests are failing outright, not just slowly, and the rate is still rising.', 'http.server.request.count{status_code>=500}', 'UP'),
  ('timeouts-up', 'Client timeouts firing', 'api', 'Callers are giving up on requests before the server answers.', 'deadline exceeded / context canceled', 'UP'),
  ('retry-rate-up', 'Retry rate climbing', 'api', 'A growing share of traffic is a second or third attempt at the same work.', 'http.request.resend_count', 'UP'),
  ('rate-limit-429s', '429s being returned', 'api', 'The service is refusing requests on purpose, by policy.', 'http.server.request.count{status_code=429}', 'UP'),
  ('oversized-responses', 'Response payloads growing', 'application', 'Responses are larger than they were, without a deliberate API change.', 'http.server.response.body.size', 'UP'),
  ('slow-request-fanout', 'Many downstream calls per request', 'application', 'One inbound request now produces a crowd of outbound calls.', 'client spans per server span', 'UP'),
  ('db-latency-up', 'Database query latency up', 'data', 'The database is taking longer per statement, with request volume unchanged.', 'db.client.operation.duration p95', 'UP'),
  ('pool-wait-up', 'Connection pool wait time up', 'data', 'Work is queuing to get a database connection before any query runs.', 'db.client.connection.pending_requests', 'UP'),
  ('lock-waits-up', 'Lock waits in the database', 'data', 'Statements are blocked waiting for a lock another session holds.', 'pg_locks where granted = false', 'UP'),
  ('deadlock-errors', 'Deadlock errors in the log', 'data', 'The database is aborting transactions to break cycles.', 'pg_stat_database.deadlocks', 'UP'),
  ('idle-in-transaction', 'Sessions idle in transaction', 'data', 'Transactions are open far longer than the statements inside them take.', 'max(now() - xact_start)', 'UP'),
  ('replica-stale-reads', 'Replicas behind the primary', 'data', 'A read replica is serving data the primary already moved past.', 'replication lag in seconds', 'UP'),
  ('stale-data-reads', 'Users see stale data after a write', 'caching', 'A value that was just written reads back as the old one.', 'stale read detected / version mismatch', 'PRESENT'),
  ('cache-hit-drop', 'Cache hit ratio dropped', 'caching', 'A larger share of reads is missing the cache than yesterday.', 'cache hit ratio', 'DOWN'),
  ('origin-load-spike', 'Origin request spike', 'caching', 'Traffic behind the cache jumped in a step, often at a round-numbered time.', 'origin request rate', 'SPIKE'),
  ('single-shard-hot', 'One node hotter than its peers', 'caching', 'Identical replicas, wildly different load on one of them.', 'ops per key / per shard', 'UP'),
  ('memory-climbing', 'Memory use climbing', 'runtime', 'The live set grows between collections and never returns to its old floor.', 'heap used after full collection', 'UP'),
  ('restart-loop', 'Processes restarting on a cadence', 'runtime', 'The process is killed and replaced on a schedule nobody wrote.', 'OOMKilled / exit code 137', 'PRESENT'),
  ('gc-pauses-up', 'Garbage-collection pauses lengthening', 'runtime', 'Collections are longer, more frequent, or both.', 'process.runtime.gc.duration', 'SPIKE'),
  ('threadpool-queueing', 'Worker pool queueing', 'runtime', 'Work waits for a worker before it starts running.', 'executor queue depth', 'UP'),
  ('event-loop-lag', 'Event loop lag spikes', 'runtime', 'The loop is late returning to the queue; everything on it is delayed.', 'event loop lag', 'SPIKE'),
  ('cpu-saturated', 'CPU pinned or throttled', 'os', 'The process is hitting its CPU ceiling, whether it owns it or not.', 'cgroup cpu.stat nr_throttled', 'UP'),
  ('disk-io-up', 'Disk read throughput up', 'os', 'Physical reads rose while the logical read rate stayed flat.', 'major page faults / read IOPS', 'UP'),
  ('fd-exhaustion-errors', 'Too many open files', 'os', 'The process cannot open another socket or file.', 'EMFILE / open fds vs RLIMIT_NOFILE', 'PRESENT'),
  ('packet-loss', 'TCP retransmits rising', 'network', 'Segments are being sent twice; something between the hosts is dropping them.', 'TcpRetransSegs', 'UP'),
  ('dns-slow', 'DNS resolution slow or failing', 'network', 'Name lookups take hundreds of milliseconds or fail intermittently.', 'DNS resolution span duration', 'SPIKE'),
  ('connection-churn-up', 'New connections per second climbing', 'network', 'Connections are being opened and closed rather than reused.', 'sockets in TIME_WAIT / connects per second', 'UP'),
  ('queue-depth-up', 'Queue depth and age growing', 'distributed', 'Producers are outpacing consumers and the backlog is not draining.', 'queue depth, oldest message age', 'UP')
ON CONFLICT (id) DO UPDATE SET
    name = excluded.name,
    layer_id = excluded.layer_id,
    description = excluded.description,
    signal = excluded.signal,
    trend = excluded.trend;

